86	/// Map screen touch coordinates to a lane number (1-4).
87	pub fn touch_to_lane(
88	    touch_x: f32,
89	    touch_y: f32,
90	    screen_width: f32,
91	    screen_height: f32,
92	    inv_view_proj: &Mat4,
93	) -> Option<u8> {
94	    let ndc_x = 2.0 * touch_x / screen_width - 1.0;
95	    let ndc_y = 1.0 - 2.0 * touch_y / screen_height;
96	
97	    let near = *inv_view_proj * Vec4::new(ndc_x, ndc_y, 0.0, 1.0);
98	    let far = *inv_view_proj * Vec4::new(ndc_x, ndc_y, 1.0, 1.0);
99	    let near = near.truncate() / near.w;
100	    let far = far.truncate() / far.w;
101	
102	    let dir = far - near;
103	    if dir.y.abs() < 1e-6 {
104	        return None;
105	    }
106	    let t = -near.y / dir.y;
107	    if t < 0.0 {
108	        return None;
109	    }
110	    let world_x = near.x + t * dir.x;
111	
112	    let lane = ((-world_x + LANE_WIDTH * 2.5) / LANE_WIDTH).round() as i32;
113	    Some(lane.clamp(1, 4) as u8)
114	}
