11	use crate::chart::types::Chart;
12	use crate::input::{self, InputManager};
13	use crate::audio::hitsound::HitsoundEngine;
14	use crate::judgment::{Grade, GreedyJudge, NoteKind};
15	use crate::render::track::HitEffect;
16	use crate::render::Gpu;
17	use crate::timing::{GameClock, LEAD_IN_MS};
18	
19	pub struct App {
20	    state: Option<AppState>,
21	    chart_path: Option<String>,
22	    audio_path: Option<String>,
23	    #[cfg(target_os = "android")]
24	    android_app: android_activity::AndroidApp,
25	}
