28	    window: Arc<Window>,
29	    gpu: Gpu,
30	    chart: Chart,
31	    clock: GameClock,
32	    input: InputManager,
33	    judge: GreedyJudge,
34	    hit_effects: Vec<HitEffect>,
35	    hitsound: Option<HitsoundEngine>,
36	    last_combo: u32,
37	    combo_flash: f32,
38	    last_frame: Instant,
39	    result_shown: bool,
40	    frame_count: u32,
41	    frame_time_accum: f32,
42	}
43	
44	impl App {
45	    #[cfg(not(target_os = "android"))]
46	    pub fn new(chart_path: Option<String>, audio_path: Option<String>) -> Self {
47	        Self {
48	            state: None,
49	            chart_path,
50	            audio_path,
51	        }
52	    }
53	
54	    #[cfg(target_os = "android")]
55	    pub fn new(android_app: android_activity::AndroidApp) -> Self {
56	        Self {
57	            state: None,
58	            chart_path: None,
59	            audio_path: None,
60	            android_app,
61	        }
62	    }
63	}
64	
65	impl ApplicationHandler for App {
66	    fn resumed(&mut self, event_loop: &ActiveEventLoop) {
67	        if self.state.is_some() {
68	            return;
69	        }
70	
71	        let window_attrs = Window::default_attributes().with_title("BetterArc");
72	        let window = Arc::new(
73	            event_loop
74	                .create_window(window_attrs)
75	                .expect("failed to create window"),
76	        );
77	
78	        // Create asset loader
79	        #[cfg(target_os = "android")]
80	        let assets = crate::assets::AssetLoader::new(&self.android_app);
81	        #[cfg(not(target_os = "android"))]
82	        let assets = crate::assets::AssetLoader::new(std::path::PathBuf::from("assets"));
83	
84	        // Load chart
85	        let chart_str = if let Some(path) = &self.chart_path {
86	            std::fs::read_to_string(path).expect("failed to read chart file")
87	        } else {
88	            assets
89	                .load_string("charts/sayonarahatsukoi_ftr.aff")
90	                .or_else(|_| assets.load_string("charts/test.aff"))
91	                .unwrap_or_else(|_| include_str!("../assets/charts/test.aff").to_string())
92	        };
93	        let chart = crate::chart::parse(&chart_str).expect("failed to parse chart");
94	        log::info!(
95	            "chart loaded: {} taps, {} holds, {} arcs",
96	            chart.groups[0].taps.len(),
97	            chart.groups[0].holds.len(),
98	            chart.groups[0].arcs.len(),
99	        );
100	
101	        let mut clock = GameClock::new(&chart);
102	
103	        // Load audio
104	        if let Some(audio_path) = &self.audio_path {
105	            let path = std::path::Path::new(audio_path);
106	            if path.exists() {
107	                match AudioEngine::play_ogg(path, LEAD_IN_MS) {
108	                    Ok(engine) => {
109	                        log::info!("audio loaded from {}", audio_path);
110	                        clock.set_audio(engine);
111	                    }
112	                    Err(e) => log::error!("failed to load audio: {e}"),
113	                }
114	            } else {
115	                log::warn!("audio file not found: {}", audio_path);
116	            }
117	        } else {
118	            match assets.load_bytes("charts/audio.ogg") {
119	                Ok(bytes) => match AudioEngine::play_ogg_bytes(bytes, LEAD_IN_MS) {
120	                    Ok(engine) => {
121	                        log::info!("audio loaded from assets");
122	                        clock.set_audio(engine);
123	                    }
124	                    Err(e) => log::error!("failed to play audio: {e}"),
125	                },
126	                Err(e) => log::info!("no audio in assets: {e}"),
127	            }
128	        }
129	
130	        let input = InputManager::new();
131	        let judge = GreedyJudge::new(&chart);
132	        let hitsound = HitsoundEngine::with_assets(&assets);
133	        if hitsound.is_some() {
134	            log::info!("hitsound engine initialized");
135	        }
136	        let gpu = pollster::block_on(Gpu::new(window.clone(), &assets));
137	
138	        self.state = Some(AppState {
139	            window,
140	            gpu,
141	            chart,
142	            clock,
143	            input,
144	            judge,
145	            hit_effects: Vec::new(),
146	            hitsound,
147	            last_combo: 0,
148	            combo_flash: 0.0,
149	            last_frame: Instant::now(),
150	            result_shown: false,
151	            frame_count: 0,
152	            frame_time_accum: 0.0,
153	        });
154	        log::info!("app initialized");
155	    }
156	
157	    fn window_event(
158	        &mut self,
159	        event_loop: &ActiveEventLoop,
160	        _window_id: WindowId,
161	        event: WindowEvent,
162	    ) {
163	        let Some(state) = &mut self.state else {
164	            return;
165	        };
166	
167	        match event {
168	            WindowEvent::CloseRequested => {
169	                event_loop.exit();
170	            }
171	            WindowEvent::Resized(size) => {
172	                if size.width > 0 && size.height > 0 {
173	                    state.gpu.resize(size.width, size.height);
174	                }
175	            }
176	            WindowEvent::KeyboardInput { event, .. } => {
177	                if state.result_shown {
178	                    if event.state == ElementState::Pressed && !event.repeat {
179	                        event_loop.exit();
180	                    }
181	                } else if let Some(lane) = input::physical_key_to_lane(&event.physical_key) {
182	                    if event.state == ElementState::Pressed && !event.repeat {
183	                        let time = state.clock.current_time_ms();
184	                        state.input.key_down(lane, time);
185	                    } else if event.state == ElementState::Released {
186	                        state.input.key_up(lane);
187	                    }
188	                }
189	            }
190	            WindowEvent::Touch(touch) => {
191	                if state.result_shown {
192	                    if touch.phase == winit::event::TouchPhase::Started {
193	                        event_loop.exit();
194	                    }
195	                } else {
196	                    let [sw, sh] = state.gpu.screen_size();
197	                    let inv_vp = state.gpu.inv_view_proj();
198	                    match touch.phase {
199	                        winit::event::TouchPhase::Started => {
200	                            if let Some(lane) = input::touch_to_lane(
201	                                touch.location.x as f32,
202	                                touch.location.y as f32,
203	                                sw as f32,
204	                                sh as f32,
205	                                &inv_vp,
206	                            ) {
207	                                let time = state.clock.current_time_ms();
208	                                state.input.touch_start(touch.id, lane, time);
209	                            }
210	                        }
211	                        winit::event::TouchPhase::Ended | winit::event::TouchPhase::Cancelled => {
212	                            state.input.touch_end(touch.id);
213	                        }
214	                        winit::event::TouchPhase::Moved => {
215	                            // Future: arc tracking
216	                        }
217	                    }
218	                }
219	            }
220	            WindowEvent::RedrawRequested => {
221	                let current_time = state.clock.current_time_ms();
222	
223	                // Check for results trigger
224	                if !state.result_shown {
225	                    let s = &state.judge.score;
226	                    if s.total_notes > 0 && s.judged_count() == s.total_notes {
227	                        state.result_shown = true;
228	                        state.gpu.show_results(&state.judge.score);
229	                        log::info!("results: score={} pure={}(+{}) far={} lost={} max_combo={}",
230	                            s.score(), s.pure_max + s.pure, s.pure_max, s.far, s.lost, s.max_combo);
231	                    }
232	                }
233	
234	                if state.result_shown {
235	                    state.gpu.render();
236	                    state.window.request_redraw();
237	                    return;
238	                }
239	
240	                // Process inputs through judgment
241	                let inputs = state.input.drain();
242	                state.judge.update(current_time, &inputs, &state.input);
243	
244	                // Collect hit effects and trigger hitsounds from recent judgments
245	                for result in &state.judge.recent {
246	                    if result.grade != Grade::Lost {
247	                        state.hit_effects.push(HitEffect {
248	                            lane: result.lane,
249	                            time_ms: result.time_ms,
250	                            grade: result.grade,
251	                        });
252	
253	                        if let Some(hs) = &state.hitsound {
254	                            match result.kind {
255	                                NoteKind::Tap | NoteKind::HoldStart => hs.play_tap(),
256	                                NoteKind::ArcTap => hs.play_arc(),
257	                                NoteKind::HoldTick => {}
258	                            }
259	                        }
260	                    }
261	                }
262	
263	                // Log score on judgment events
264	                if !state.judge.recent.is_empty() {
265	                    let s = &state.judge.score;
266	                    log::info!(
267	                        "score: {} | combo: {} | P:{}/p:{}/F:{}/L:{} [{}/{}]",
268	                        s.score(),
269	                        s.combo,
270	                        s.pure_max,
271	                        s.pure,
272	                        s.far,
273	                        s.lost,
274	                        s.judged_count(),
275	                        s.total_notes,
276	                    );
277	                    state.judge.recent.clear();
278	                }
279	
280	                // Frame timing
281	                let now = Instant::now();
282	                let dt = now.duration_since(state.last_frame).as_secs_f32();
283	                state.last_frame = now;
284	
285	                let combo = state.judge.score.combo;
286	                if state.last_combo > 0 && combo == 0 {
287	                    state.combo_flash = 1.0;
