use std::sync::Arc;
use std::time::Instant;
use winit::{
    application::ApplicationHandler,
    event::{ElementState, WindowEvent},
    event_loop::{ActiveEventLoop, EventLoop},
    window::{Window, WindowId},
};

use crate::audio::AudioEngine;
use crate::chart::types::Chart;
use crate::input::{self, InputManager};
use crate::audio::hitsound::HitsoundEngine;
use crate::judgment::{Grade, GreedyJudge, NoteKind};
use crate::render::track::HitEffect;
use crate::render::Gpu;
use crate::timing::{GameClock, LEAD_IN_MS};

pub struct App {
    state: Option<AppState>,
    chart_path: Option<String>,
    audio_path: Option<String>,
    #[cfg(target_os = "android")]
    android_app: android_activity::AndroidApp,
}

struct AppState {
    window: Arc<Window>,
    gpu: Gpu,
    chart: Chart,
    clock: GameClock,
    input: InputManager,
    judge: GreedyJudge,
    hit_effects: Vec<HitEffect>,
    hitsound: Option<HitsoundEngine>,
    last_combo: u32,
    combo_flash: f32,
    last_frame: Instant,
    result_shown: bool,
    frame_count: u32,
    frame_time_accum: f32,
}

impl App {
    #[cfg(not(target_os = "android"))]
    pub fn new(chart_path: Option<String>, audio_path: Option<String>) -> Self {
        Self {
            state: None,
            chart_path,
            audio_path,
        }
    }

    #[cfg(target_os = "android")]
    pub fn new(android_app: android_activity::AndroidApp) -> Self {
        Self {
            state: None,
            chart_path: None,
            audio_path: None,
            android_app,
        }
    }
}

impl ApplicationHandler for App {
    fn resumed(&mut self, event_loop: &ActiveEventLoop) {
        if self.state.is_some() {
            return;
        }

        let window_attrs = Window::default_attributes().with_title("BetterArc");
        let window = Arc::new(
            event_loop
                .create_window(window_attrs)
                .expect("failed to create window"),
        );

        // Create asset loader
        #[cfg(target_os = "android")]
        let assets = crate::assets::AssetLoader::new(&self.android_app);
        #[cfg(not(target_os = "android"))]
        let assets = crate::assets::AssetLoader::new(std::path::PathBuf::from("assets"));

        // Load chart
        let chart_str = if let Some(path) = &self.chart_path {
            std::fs::read_to_string(path).expect("failed to read chart file")
        } else {
            assets
                .load_string("charts/sayonarahatsukoi_ftr.aff")
                .or_else(|_| assets.load_string("charts/test.aff"))
                .unwrap_or_else(|_| include_str!("../assets/charts/test.aff").to_string())
        };
        let chart = crate::chart::parse(&chart_str).expect("failed to parse chart");
        log::info!(
            "chart loaded: {} taps, {} holds, {} arcs",
            chart.groups[0].taps.len(),
            chart.groups[0].holds.len(),
            chart.groups[0].arcs.len(),
        );

        let mut clock = GameClock::new(&chart);

        // Load audio
        if let Some(audio_path) = &self.audio_path {
            let path = std::path::Path::new(audio_path);
            if path.exists() {
                match AudioEngine::play_ogg(path, LEAD_IN_MS) {
                    Ok(engine) => {
                        log::info!("audio loaded from {}", audio_path);
                        clock.set_audio(engine);
                    }
                    Err(e) => log::error!("failed to load audio: {e}"),
                }
            } else {
                log::warn!("audio file not found: {}", audio_path);
            }
        } else {
            match assets.load_bytes("charts/audio.ogg") {
                Ok(bytes) => match AudioEngine::play_ogg_bytes(bytes, LEAD_IN_MS) {
                    Ok(engine) => {
                        log::info!("audio loaded from assets");
                        clock.set_audio(engine);
                    }
                    Err(e) => log::error!("failed to play audio: {e}"),
                },
                Err(e) => log::info!("no audio in assets: {e}"),
            }
        }

        let input = InputManager::new();
        let judge = GreedyJudge::new(&chart);
        let hitsound = HitsoundEngine::with_assets(&assets);
        if hitsound.is_some() {
            log::info!("hitsound engine initialized");
        }
        let gpu = pollster::block_on(Gpu::new(window.clone(), &assets));

        self.state = Some(AppState {
            window,
            gpu,
            chart,
            clock,
            input,
            judge,
            hit_effects: Vec::new(),
            hitsound,
            last_combo: 0,
            combo_flash: 0.0,
            last_frame: Instant::now(),
            result_shown: false,
            frame_count: 0,
            frame_time_accum: 0.0,
        });
        log::info!("app initialized");
    }

    fn window_event(
        &mut self,
        event_loop: &ActiveEventLoop,
        _window_id: WindowId,
        event: WindowEvent,
    ) {
        let Some(state) = &mut self.state else {
            return;
        };

        match event {
            WindowEvent::CloseRequested => {
                event_loop.exit();
            }
            WindowEvent::Resized(size) => {
                if size.width > 0 && size.height > 0 {
                    state.gpu.resize(size.width, size.height);
                }
            }
            WindowEvent::KeyboardInput { event, .. } => {
                if state.result_shown {
                    if event.state == ElementState::Pressed && !event.repeat {
                        event_loop.exit();
                    }
                } else if let Some(lane) = input::physical_key_to_lane(&event.physical_key) {
                    if event.state == ElementState::Pressed && !event.repeat {
                        let time = state.clock.current_time_ms();
                        state.input.key_down(lane, time);
                    } else if event.state == ElementState::Released {
                        state.input.key_up(lane);
                    }
                }
            }
            WindowEvent::Touch(touch) => {
                if state.result_shown {
                    if touch.phase == winit::event::TouchPhase::Started {
                        event_loop.exit();
                    }
                } else {
                    let [sw, sh] = state.gpu.screen_size();
                    let inv_vp = state.gpu.inv_view_proj();
                    match touch.phase {
                        winit::event::TouchPhase::Started => {
                            if let Some(lane) = input::touch_to_lane(
                                touch.location.x as f32,
                                touch.location.y as f32,
                                sw as f32,
                                sh as f32,
                                &inv_vp,
                            ) {
                                let time = state.clock.current_time_ms();
                                state.input.touch_start(touch.id, lane, time);
                            }
                        }
                        winit::event::TouchPhase::Ended | winit::event::TouchPhase::Cancelled => {
                            state.input.touch_end(touch.id);
                        }
                        winit::event::TouchPhase::Moved => {
                            // Future: arc tracking
                        }
                    }
                }
            }
            WindowEvent::RedrawRequested => {
                let current_time = state.clock.current_time_ms();

                // Check for results trigger
                if !state.result_shown {
                    let s = &state.judge.score;
                    if s.total_notes > 0 && s.judged_count() == s.total_notes {
                        state.result_shown = true;
                        state.gpu.show_results(&state.judge.score);
                        log::info!("results: score={} pure={}(+{}) far={} lost={} max_combo={}",
                            s.score(), s.pure_max + s.pure, s.pure_max, s.far, s.lost, s.max_combo);
                    }
                }

                if state.result_shown {
                    state.gpu.render();
                    state.window.request_redraw();
                    return;
                }

                // Process inputs through judgment
                let inputs = state.input.drain();
                state.judge.update(current_time, &inputs, &state.input);

                // Collect hit effects and trigger hitsounds from recent judgments
                for result in &state.judge.recent {
                    if result.grade != Grade::Lost {
                        state.hit_effects.push(HitEffect {
                            lane: result.lane,
                            time_ms: result.time_ms,
                            grade: result.grade,
                        });

                        if let Some(hs) = &state.hitsound {
                            match result.kind {
                                NoteKind::Tap | NoteKind::HoldStart => hs.play_tap(),
                                NoteKind::ArcTap => hs.play_arc(),
                                NoteKind::HoldTick => {}
                            }
                        }
                    }
                }

                // Log score on judgment events
                if !state.judge.recent.is_empty() {
                    let s = &state.judge.score;
                    log::info!(
                        "score: {} | combo: {} | P:{}/p:{}/F:{}/L:{} [{}/{}]",
                        s.score(),
                        s.combo,
                        s.pure_max,
                        s.pure,
                        s.far,
                        s.lost,
                        s.judged_count(),
                        s.total_notes,
                    );
                    state.judge.recent.clear();
                }

                // Frame timing
                let now = Instant::now();
                let dt = now.duration_since(state.last_frame).as_secs_f32();
                state.last_frame = now;

                let combo = state.judge.score.combo;
                if state.last_combo > 0 && combo == 0 {
                    state.combo_flash = 1.0;
                }
                state.last_combo = combo;
                state.combo_flash = (state.combo_flash - dt / 0.1).max(0.0);

                // Update HUD
                state.gpu.update_hud(combo, state.judge.score.score(), state.combo_flash);

                // Expire old hit effects (>300ms)
                state
                    .hit_effects
                    .retain(|e| current_time - e.time_ms < 300);

                state.gpu.update_notes(
                    &state.chart,
                    &state.clock,
                    current_time,
                    &state.judge,
                    &state.hit_effects,
                );
                state.gpu.render();
                state.frame_count += 1;
                state.frame_time_accum += dt;
                if state.frame_count % 120 == 0 {
                    log::info!("fps: {:.0} (frame {:.1}ms)",
                        120.0 / state.frame_time_accum,
                        state.frame_time_accum / 120.0 * 1000.0);
                    state.frame_time_accum = 0.0;
                }
                state.window.request_redraw();
            }
            _ => {}
        }
    }
}

#[cfg(not(target_os = "android"))]
pub fn run_app() {
    let args: Vec<String> = std::env::args().collect();
    // Usage: better-arc [chart.aff] [audio.ogg]
    let chart_path = args.get(1).cloned();
    let audio_path = args.get(2).cloned();

    if chart_path.is_some() {
        log::info!("chart: {}", chart_path.as_deref().unwrap());
    }
    if audio_path.is_some() {
        log::info!("audio: {}", audio_path.as_deref().unwrap());
    }

    let event_loop = EventLoop::new().expect("failed to create event loop");
    let mut app = App::new(chart_path, audio_path);
    event_loop.run_app(&mut app).expect("event loop error");
}

