437	    fn upload_mesh(&mut self, mesh: &(Vec<Vertex>, Vec<u32>), which: &str) {
438	        let (verts, idxs) = mesh;
439	        let buf = match which {
440	            "note_taps" => &mut self.note_taps,
441	            "note_holds" => &mut self.note_holds,
442	            "note_arcs" => &mut self.note_arcs,
443	            "note_arc_caps" => &mut self.note_arc_caps,
444	            "note_sky" => &mut self.note_sky,
445	            "fx_lane" => &mut self.fx_lane,
446	            "fx_pure" => &mut self.fx_pure,
447	            "fx_far" => &mut self.fx_far,
448	            _ => return,
449	        };
450	        buf.index_count = idxs.len() as u32;
451	
452	        if verts.is_empty() {
453	            return;
454	        }
455	
456	        let vert_bytes = bytemuck::cast_slice(verts);
457	        let idx_bytes = bytemuck::cast_slice(idxs);
458	
459	        if vert_bytes.len() as u64 > buf.vertex.size() {
460	            buf.vertex = self.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
461	                label: Some(&format!("{which}_verts")),
462	                contents: vert_bytes,
463	                usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
464	            });
465	        } else {
466	            self.queue.write_buffer(&buf.vertex, 0, vert_bytes);
467	        }
468	
