    /// Update note geometry for the current frame.
    pub fn update_notes(
        &mut self,
        chart: &Chart,
        clock: &GameClock,
        current_time: Ms,
        judge: &crate::judgment::GreedyJudge,
        hit_effects: &[super::track::HitEffect],
    ) {
        let geo = super::track::build_note_geometry(chart, clock, current_time, judge, hit_effects);
        self.upload_mesh(&geo.taps, "note_taps");
        self.upload_mesh(&geo.holds, "note_holds");
        self.upload_mesh(&geo.arcs, "note_arcs");
        self.upload_mesh(&geo.arc_caps, "note_arc_caps");
        self.upload_mesh(&geo.sky, "note_sky");
        self.upload_mesh(&geo.lane_hits, "fx_lane");
        self.upload_mesh(&geo.hit_pure, "fx_pure");
        self.upload_mesh(&geo.hit_far, "fx_far");
    }

    pub fn update_hud(&mut self, combo: u32, score: u64, combo_flash: f32) {
        if let Some(hud) = &mut self.hud {
            hud.set_combo(combo, combo_flash);
            hud.set_score(score);
        }
    }

    pub fn inv_view_proj(&self) -> glam::Mat4 {
        self.camera.inv_view_proj()
    }

    pub fn poll_wait(&self) {
        self.device.poll(wgpu::Maintain::Wait);
    }

    pub fn screen_size(&self) -> [u32; 2] {
        [self.config.width, self.config.height]
    }

    pub fn show_results(&mut self, score: &crate::judgment::ScoreState) {
        if let Some(hud) = &mut self.hud {
            hud.set_results(score);
        }
        self.show_results = true;
    }

    fn upload_mesh(&mut self, mesh: &(Vec<Vertex>, Vec<u32>), which: &str) {
        let (verts, idxs) = mesh;
        let buf = match which {
            "note_taps" => &mut self.note_taps,
            "note_holds" => &mut self.note_holds,
            "note_arcs" => &mut self.note_arcs,
            "note_arc_caps" => &mut self.note_arc_caps,
            "note_sky" => &mut self.note_sky,
            "fx_lane" => &mut self.fx_lane,
            "fx_pure" => &mut self.fx_pure,
            "fx_far" => &mut self.fx_far,
            _ => return,
        };
        buf.index_count = idxs.len() as u32;

        if verts.is_empty() {
            return;
        }

        let vert_bytes = bytemuck::cast_slice(verts);
        let idx_bytes = bytemuck::cast_slice(idxs);

        if vert_bytes.len() as u64 > buf.vertex.size() {
            buf.vertex = self.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
                label: Some(&format!("{which}_verts")),
                contents: vert_bytes,
                usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
            });
        } else {
            self.queue.write_buffer(&buf.vertex, 0, vert_bytes);
        }

        if idx_bytes.len() as u64 > buf.index.size() {
            buf.index = self.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
                label: Some(&format!("{which}_idxs")),
                contents: idx_bytes,
                usage: wgpu::BufferUsages::INDEX | wgpu::BufferUsages::COPY_DST,
            });
        } else {
            self.queue.write_buffer(&buf.index, 0, idx_bytes);
        }
    }

    pub fn resize(&mut self, width: u32, height: u32) {
        self.config.width = width;
        self.config.height = height;
        self.surface.configure(&self.device, &self.config);
        self.depth_view = create_depth_texture(&self.device, width, height);

        self.camera.aspect = width as f32 / height as f32;
        self.camera.far = {
            let eye_z = height as f32 / 2.0 / (30.0_f32.to_radians().tan());
            eye_z + height as f32 * 0.5
        };
        let uniform = CameraUniform::from(&self.camera);
        self.queue
            .write_buffer(&self.camera_buffer, 0, bytemuck::cast_slice(&[uniform]));
    }

    pub fn render(&mut self) {
        // Prepare HUD text before render pass
        let screen = [self.config.width, self.config.height];
        if let Some(hud) = &mut self.hud {
            if self.show_results {
                hud.prepare_results(&self.device, &self.queue, screen);
            } else {
                hud.prepare(&self.device, &self.queue, screen);
            }
        }

        let output = match self.surface.get_current_texture() {
            Ok(t) => t,
            Err(wgpu::SurfaceError::Lost | wgpu::SurfaceError::Outdated) => {
                self.surface.configure(&self.device, &self.config);
                return;
            }
            Err(e) => {
                log::error!("surface error: {e:?}");
                return;
            }
        };

        let view = output
            .texture
            .create_view(&wgpu::TextureViewDescriptor::default());

        let mut encoder = self
            .device
            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                label: Some("frame"),
            });

        self.encode_render_pass(&mut encoder, &view, &self.depth_view);

        self.queue.submit(std::iter::once(encoder.finish()));
        output.present();
    }

    /// Encode the full render pass into the given encoder.
    fn encode_render_pass(
        &self,
        encoder: &mut wgpu::CommandEncoder,
        color_view: &wgpu::TextureView,
        depth_view: &wgpu::TextureView,
    ) {
        {
            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("main"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                    view: color_view,
                    resolve_target: None,
                    ops: wgpu::Operations {
                        load: wgpu::LoadOp::Clear(wgpu::Color {
                            r: 0.02,
                            g: 0.02,
                            b: 0.06,
                            a: 1.0,
                        }),
                        store: wgpu::StoreOp::Store,
                    },
                })],
                depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
                    view: depth_view,
                    depth_ops: Some(wgpu::Operations {
                        load: wgpu::LoadOp::Clear(1.0),
                        store: wgpu::StoreOp::Store,
                    }),
                    stencil_ops: None,
                }),
                ..Default::default()
            });

            pass.set_pipeline(&self.pipeline);
            pass.set_bind_group(0, &self.camera_bind_group, &[]);

            // 1. Track surface (track.png)
            pass.set_bind_group(1, &self.tex_track, &[]);
            self.draw_mesh(&mut pass, &self.track_surface);

            // 2. Lane dividers (track_lane_divider.png)
            pass.set_bind_group(1, &self.tex_divider, &[]);
            self.draw_mesh(&mut pass, &self.track_dividers);

            // 3. Judgment line (track_critical_line.png)
            pass.set_bind_group(1, &self.tex_judgment, &[]);
            self.draw_mesh(&mut pass, &self.track_judgment);

            // 4. Arc bodies (arc_body.png)
            pass.set_bind_group(1, &self.tex_arc_body, &[]);
            self.draw_mesh(&mut pass, &self.note_arcs);

            // 4b. Arc caps (arc_cap.png)
            pass.set_bind_group(1, &self.tex_arc_cap, &[]);
            self.draw_mesh(&mut pass, &self.note_arc_caps);

            // 5. Tap notes (note.png)
            pass.set_bind_group(1, &self.tex_note, &[]);
            self.draw_mesh(&mut pass, &self.note_taps);

            // 6. Hold notes (note_hold.png)
            pass.set_bind_group(1, &self.tex_hold, &[]);
            self.draw_mesh(&mut pass, &self.note_holds);

            // 7. Sky notes (solid cyan — white tex × cyan vertex color)
            pass.set_bind_group(1, &self.tex_white, &[]);
            self.draw_mesh(&mut pass, &self.note_sky);

            // 8. Lane glow (lane_hit.png)
            pass.set_bind_group(1, &self.tex_lane_hit, &[]);
            self.draw_mesh(&mut pass, &self.fx_lane);

            // 9. Pure hit effect (hit_pure.png)
            pass.set_bind_group(1, &self.tex_hit_pure, &[]);
            self.draw_mesh(&mut pass, &self.fx_pure);

            // 10. Far hit effect (hit_far.png)
            pass.set_bind_group(1, &self.tex_hit_far, &[]);
            self.draw_mesh(&mut pass, &self.fx_far);

            // 11. HUD text overlay (combo + score)
            if let Some(hud) = &self.hud {
                hud.render(&mut pass);
            }
        }
    }

    /// Capture the current frame to an RGBA image.
    ///
    /// Renders to an offscreen texture and reads back the pixels.
    /// Call `update_notes()` before this to set up the scene.
    pub fn capture_frame(&self) -> image::RgbaImage {
        let width = self.config.width;
        let height = self.config.height;
        let format = self.config.format;

        // Offscreen render target
        let capture_tex = self.device.create_texture(&wgpu::TextureDescriptor {
            label: Some("capture"),
            size: wgpu::Extent3d { width, height, depth_or_array_layers: 1 },
            mip_level_count: 1,
            sample_count: 1,
            dimension: wgpu::TextureDimension::D2,
            format,
            usage: wgpu::TextureUsages::RENDER_ATTACHMENT | wgpu::TextureUsages::COPY_SRC,
            view_formats: &[],
        });
        let capture_view = capture_tex.create_view(&wgpu::TextureViewDescriptor::default());

        // Separate depth buffer for capture (same dimensions)
        let capture_depth = create_depth_texture(&self.device, width, height);

        let mut encoder = self.device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
            label: Some("capture"),
        });

        self.encode_render_pass(&mut encoder, &capture_view, &capture_depth);

        // Copy texture to readback buffer
        let bytes_per_pixel = 4u32;
        let unpadded_bpr = width * bytes_per_pixel;
        let align = wgpu::COPY_BYTES_PER_ROW_ALIGNMENT;
        let padded_bpr = (unpadded_bpr + align - 1) / align * align;

        let buffer = self.device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("capture_readback"),
            size: (padded_bpr * height) as u64,
            usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
            mapped_at_creation: false,
        });

        encoder.copy_texture_to_buffer(
            wgpu::ImageCopyTexture {
                texture: &capture_tex,
                mip_level: 0,
                origin: wgpu::Origin3d::ZERO,
                aspect: wgpu::TextureAspect::All,
            },
            wgpu::ImageCopyBuffer {
                buffer: &buffer,
                layout: wgpu::ImageDataLayout {
                    offset: 0,
                    bytes_per_row: Some(padded_bpr),
                    rows_per_image: Some(height),
                },
            },
            wgpu::Extent3d { width, height, depth_or_array_layers: 1 },
        );

        self.queue.submit(std::iter::once(encoder.finish()));

        // Map buffer and read pixels
        let buffer_slice = buffer.slice(..);
        let (sender, receiver) = std::sync::mpsc::channel();
        buffer_slice.map_async(wgpu::MapMode::Read, move |result| {
            sender.send(result).unwrap();
        });
        self.device.poll(wgpu::Maintain::Wait);
        receiver.recv().unwrap().unwrap();

        let data = buffer_slice.get_mapped_range();
        let mut pixels = Vec::with_capacity((width * height * 4) as usize);
        for chunk in data.chunks(padded_bpr as usize) {
            pixels.extend_from_slice(&chunk[..unpadded_bpr as usize]);
        }
        drop(data);
        buffer.unmap();

        // BGRA -> RGBA conversion if needed
        let is_bgra = matches!(
            format,
            wgpu::TextureFormat::Bgra8Unorm | wgpu::TextureFormat::Bgra8UnormSrgb
        );
        if is_bgra {
            for pixel in pixels.chunks_exact_mut(4) {
                pixel.swap(0, 2);
            }
        }

        image::RgbaImage::from_raw(width, height, pixels).expect("failed to create image from capture")
    }

    fn draw_mesh<'a>(&'a self, pass: &mut wgpu::RenderPass<'a>, mesh: &'a MeshBuffer) {
        if mesh.index_count == 0 {
            return;
        }
        pass.set_vertex_buffer(0, mesh.vertex.slice(..));
        pass.set_index_buffer(mesh.index.slice(..), wgpu::IndexFormat::Uint32);
        pass.draw_indexed(0..mesh.index_count, 0, 0..1);
    }
}

