/// Current chart time in milliseconds.
/// If audio is attached, uses audio position with wall-clock interpolation
/// to eliminate quantization jitter between audio callbacks.
pub fn current_time_ms(&mut self) -> Ms {
    if let Some(audio) = &self.audio {
        let raw_ms = audio.position_ms() - self.offset_ms;
        let now = Instant::now();

        if raw_ms != self.last_raw_ms {
            self.last_raw_ms = raw_ms;
            self.last_audio_sync = now;
        }

        let wall_elapsed = now.duration_since(self.last_audio_sync).as_millis() as Ms;
        self.last_raw_ms + wall_elapsed
    } else {
        // Wall-clock fallback with lead-in delay
        let elapsed = self.start.elapsed().as_millis() as Ms;
        elapsed - self.offset_ms - LEAD_IN_MS
    }
}

